  "pricing.faq.trialA": "새 계정에는 코드 입력 없이 7일 무료 체험이 자동 제공됩니다. 카드 정보는 입력해야 하지만 7일 동안은 요금이 청구되지 않습니다. 7일 후 구독이 자동으로 시작되며, 체험 기간 중에는 언제든지 해지할 수 있습니다.",
