  "stuSess.refundContactNote": "환불을 원하시면 <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>로 문의하세요.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">문의 사항이나 문제가 있나요? <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>로 연락하세요.</p><p class=\"font-semibold text-emerald-900\">Stripe를 통해 환불 절차가 시작되었습니다.</p><p class=\"text-emerald-800 mt-1\">카드 환불은 보통 <strong>5–10영업일</strong> 정도 걸립니다(은행에 따라 다를 수 있음). 일반적인 처리 기간 내에 환불받지 못하면 <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>로 이메일을 보내세요.</p>",
  "stuSess.refundSuccessManualTutor": "<p>이 수업은 Tutlio Stripe로 결제되지 않은 것으로 보입니다(예: 계좌이체 또는 현금). 여기에서는 자동 환불이 이루어지지 않습니다.</p><p class=\"mt-2\">환불을 진행하려면 튜터 <strong>{tutor}</strong>님에게 문의하세요. 예약 내역의 이메일이나 연락처 또는 튜터가 직접 제공한 연락처를 이용하세요.</p>",
  "stuSess.refundSuccessManualOrg": "<p>이 수업은 Tutlio Stripe로 결제되지 않은 것으로 보입니다(예: 계좌이체 또는 현금). 여기에서는 자동 환불이 이루어지지 않습니다.</p><p class=\"mt-2\">기관을 통해 수업을 이용 중이므로 <strong>기관 관리자</strong>에게 문의하세요(튜터를 통하거나 기관이 공개한 연락처 이용).</p>",
  "stuSess.refundTutorFallback": "담당 튜터",
