  "landing.faq.whatIsQ": "Tutlio란 무엇인가요?",
  "landing.faq.whatIsA": "Tutlio는 개인 튜터와 튜터링 학교가 일정, 결제, 학생과의 소통, 수업 기록을 한곳에서 관리할 수 있도록 돕는 튜터링 관리 플랫폼입니다.",
  "landing.faq.whoForQ": "누가 Tutlio를 사용할 수 있나요?",
  "landing.faq.whoForA": "Tutlio는 개인 튜터, 음악 교사, 언어 강사, 수학 튜터, 튜터링 학교, 모든 규모의 교육기관을 위해 설계되었습니다.",
  "landing.faq.waitlistQ": "학생 대기 목록은 어떻게 작동하나요?",
  "landing.faq.waitlistA": "학생이 수업을 취소하면 비게 된 시간대가 대기 목록의 학생들에게 자동으로 제안됩니다. 가장 먼저 확인한 학생이 예약하므로 튜터는 취소로 인한 수입 손실을 막을 수 있습니다.",
  "landing.faq.freeTrialQ": "무료 체험이 있나요?",
  "landing.faq.freeTrialA": "네! 모든 새 계정에 코드 입력 없이 7일 무료 체험이 자동 제공됩니다. 체험 기간에는 요금이 청구되지 않으며 언제든지 해지할 수 있습니다.",
  "landing.faq.languagesQ": "Tutlio는 어떤 언어를 지원하나요?",
  "landing.faq.languagesA": "Tutlio는 {count}개 언어로 제공됩니다: {languages}.",
  "landing.faqTitle": "자주 묻는 질문",
  "landing.feature.digital-business-card": "디지털 명함",
  "landing.feature.digital-business-cardDesc": "학생이 튜터 소개와 실시간 수업료, 예약 가능 시간을 확인하고 바로 수업을 요청할 수 있는 전문적인 페이지를 공유하세요.",
  "featuresIndex.newBadge": "새 기능",
  "feature.digital-business-card.pageTitle": "관심을 수업 요청으로 이어 주는 디지털 명함",
  "feature.digital-business-card.pageDesc": "소개, 수업, 수업료, 후기, 실시간 예약 가능 시간을 담은 링크를 예비 학생에게 전달하세요. 학생이 바로 수업과 시간을 선택하므로 긴 메시지 대화 속에서 문의를 놓치지 않게 됩니다.",
  "feature.digital-business-card.detailsTitle": "예비 학생이 수업을 결정하는 데 필요한 모든 정보",
  "feature.digital-business-card.oneLink": "튜터 비즈니스 전체를 담은 하나의 링크",
  "feature.digital-business-card.oneLinkDesc": "흩어진 소셜 프로필, 가격표, 예약 메시지를 어디서나 공유할 수 있는 하나의 페이지로 통합하세요.",
  "feature.digital-business-card.liveAvailability": "항상 최신 상태인 예약 가능 시간",
  "feature.digital-business-card.liveAvailabilityDesc": "Tutlio 캘린더에서 예약 가능 시간을 바로 가져오므로 실제로 수업하려는 시간대에만 요청을 받습니다.",
  "feature.digital-business-card.instantEnquiries": "수업 중에도 도착하는 수업 요청",
  "feature.digital-business-card.instantEnquiriesDesc": "학부모나 학생이 수업, 진행 방식, 시간을 선택하고 연락처를 남깁니다. 일정을 조율하는 대화 없이 완성된 요청을 받으세요.",
  "feature.digital-business-card.professionalBrand": "전문성이 느껴지는 첫인상",
  "feature.digital-business-card.professionalBrandDesc": "어떤 휴대폰에서도 보기 좋은 페이지에 사진, 수업 방식, 과목, 수업료, 인증된 후기, 브랜드 색상을 담으세요.",
  "feature.digital-business-card.faq.whatShowsQ": "디지털 명함에 어떤 정보를 표시할 수 있나요?",
  "feature.digital-business-card.faq.whatShowsA": "자기소개, 과목, 수업 진행 방식, 공개 수업료, 캘린더의 예약 가능 시간, 위치, 사용 언어, 소셜 링크, 인증된 학생 후기를 표시할 수 있습니다.",
  "feature.digital-business-card.faq.howBookingWorksQ": "고객이 수업을 예약하면 바로 확정되나요?",
  "feature.digital-business-card.faq.howBookingWorksA": "고객은 수업과 예약 가능한 시간을 선택한 후 예약 요청을 보냅니다. Tutlio에서 요청을 받은 뒤 새 학생을 확인하면 수업을 일정에 추가할 수 있습니다.",
  "feature.digital-business-card.faq.whereShareQ": "페이지를 어디에 공유하면 좋을까요?",
  "feature.digital-business-card.faq.whereShareA": "Instagram, TikTok, Facebook 그룹, 광고, 이메일 서명, 메시지, QR 코드에 활용하세요. 수업료나 캘린더가 변경되어도 같은 링크에서 최신 정보를 확인할 수 있습니다.",
  "feature.digital-business-card.demo.eyebrow": "직접 체험하는 고객 화면",
  "feature.digital-business-card.demo.title": "예약 과정을 체험해 보세요",
  "feature.digital-business-card.demo.desc": "아래에서 수업과 시간을 선택하세요. 새 고객은 공유된 링크에서 이렇게 간단하게 요청을 보낼 수 있습니다.",
  "feature.digital-business-card.demo.profile": "수학 튜터 · 9–12학년",
  "feature.digital-business-card.demo.available": "신규 학생 모집 중",
