  "pwa.guideIntro": "휴대폰 홈 화면에 Tutlio를 추가하면 전체 화면과 빠른 접근 기능을 갖춘 일반 앱처럼 사용할 수 있습니다.",
  "pwa.iosStep1": "Safari에서 Tutlio를 열고 화면 하단의 공유 버튼(화살표가 있는 사각형)을 누르세요.",
