  "enterpriseSuccess.checkEmail": "이메일을 확인하세요. 관리자 비밀번호를 설정하고 기관 대시보드에 접속할 수 있는 링크를 보냈습니다. 도착까지 잠시 걸릴 수 있습니다.",
  "enterpriseSuccess.backHome": "홈페이지로 돌아가기",
  "landing.leadSuccess": "감사합니다! 곧 연락드리겠습니다.",
  "orgTutorPolicy.title": "튜터 내부 규정",
  "orgTutorPolicy.intro": "플랫폼을 이용하기 전에 기관의 내부 규정을 확인해 주세요.",
  "orgTutorPolicy.acceptBtn": "확인했습니다",
  "orgTutorPolicy.viewBtn": "내부 규정 보기",
  "orgTutorPolicy.s1Title": "1. 일반 조항",
  "orgTutorPolicy.s1Body": "본 규정은 교사 또는 튜터(이하 ‘튜터’)의 Tutlio 플랫폼(이하 ‘플랫폼’) 이용에 적용됩니다. 튜터는 자신이 소속된 교육기관, 학교 또는 튜터링 센터(이하 ‘기관’)의 초대로 플랫폼을 이용합니다. 플랫폼의 기술 유지보수 및 지원은 MB Tutlio가 담당합니다. 계정을 이용하면 본 규정 및 개인정보 처리방침에 동의하는 것으로 간주됩니다.",
  "orgTutorPolicy.s2Title": "2. 계정 및 일정 관리",
  "orgTutorPolicy.s2Intro": "플랫폼은 학생과 수업 시간을 조율하는 데 시간을 쓰지 않도록 설계되었습니다.",
  "orgTutorPolicy.s2Link": "고유 링크: 담당 과목을 기준으로 개인 수업 예약 링크가 부여되며, 학생은 이 링크를 통해 수업을 예약합니다.",
  "orgTutorPolicy.s2Calendar": "캘린더 동기화: 수업 가능 시간은 Google Calendar 연동(2방향 동기화)에 직접적으로 좌우됩니다. 캘린더에 표시된 수업 가능 시간이 정확하고 최신 상태인지 확인할 책임은 튜터 본인에게 있습니다. 플랫폼은 캘린더에서 일정이 있는 것으로 표시된 시간에 학생이 예약하지 못하도록 합니다.",
  "orgTutorPolicy.s2Security": "계정 보안: 계정은 개인용입니다. 로그인 정보를 안전하게 보관하고 제삼자와 공유하지 않아야 합니다.",
  "orgTutorPolicy.s3Title": "3. 수업 취소 및 대기 목록",
  "orgTutorPolicy.s3Intro": "플랫폼은 수업 시간을 최대한 활용하고 빈 시간대를 줄일 수 있도록 돕습니다.",
  "orgTutorPolicy.s3Auto": "학생이 수업을 취소하면 플랫폼은 대기 목록의 다른 학생에게 알림(SMS/이메일)을 자동 발송하여 빈 시간대를 제안합니다. 튜터가 추가로 해야 할 작업은 없습니다.",
  "orgTutorPolicy.s3Rules": "수업 취소 규칙(취소 가능 기한 및 취소 시 적용 사항)은 기관이 정합니다.",
  "orgTutorPolicy.s4Title": "4. 재무 및 결제",
  "orgTutorPolicy.s4Intro": "청구서를 발행하거나 학부모에게 수업료를 수금하는 일을 직접 처리할 필요가 없습니다.",
  "orgTutorPolicy.s4Advance": "학생(또는 학부모)의 수업료는 모두 플랫폼을 통해 선불로 수금되어 기관에 직접 이체됩니다.",
  "orgTutorPolicy.s4Confirmed": "시스템에서 확정된 수업(이미 결제가 이루어진 수업)만 진행합니다.",
  "orgTutorPolicy.s4Contact": "급여, 지급 일정 및 기타 재무 관련 사항은 기관 관리자에게 직접 문의하세요. MB Tutlio는 튜터와 직접적인 금융 거래를 하지 않습니다.",
  "orgTutorPolicy.s5Title": "5. 학생 데이터 보호 (GDPR)",
  "orgTutorPolicy.s5Intro": "튜터는 학생의 개인정보, 내부 메모, 학습 자료에 접근할 수 있습니다. 튜터는 다음 사항을 준수해야 합니다.",
  "orgTutorPolicy.s5Use": "해당 데이터를 수업의 편성 및 진행 목적으로만 사용합니다.",
  "orgTutorPolicy.s5NoCopy": "학생이나 학부모의 연락처 정보를 플랫폼 외부로 복사, 내보내기 또는 배포하지 않습니다.",
  "orgTutorPolicy.s5Notes": "학생이나 학부모에게는 보이지 않고 튜터와 기관 관리자에게만 공개되는 기관 내부 기록(학생의 학습 진행 상황에 관한 메모)을 보호합니다.",
  "orgTutorPolicy.s5Termination": "기관과의 업무 관계가 종료되면 해당 데이터에 대한 접근 권한이 즉시 철회됩니다.",
  "orgTutorPolicy.s6Title": "6. 기술적 운영 및 책임 제한",
  "orgTutorPolicy.s6Body": "플랫폼을 불법적인 목적으로 이용하거나 수업 자료에 악성 링크를 배포하거나 그 밖의 방법으로 시스템을 방해하는 행위는 금지됩니다. MB Tutlio는 플랫폼의 운영과 기술 유지보수를 담당하지만, 튜터의 인터넷 연결, 기기 고장 또는 잘못 설정된 Google Calendar로 인한 장애에 대해서는 책임을 지지 않습니다.",
  "orgTutorPolicy.s7Title": "7. 지원 및 연락처",
  "orgTutorPolicy.s7Org": "수업 일정, 급여, 학생 배정 또는 업무 운영에 관한 질문은 기관 관리자에게 문의하세요.",
  "orgTutorPolicy.s7Tech": "플랫폼의 기술적 오류(캘린더 동기화 불가, 알림 미수신)가 발생하면 기관 관리자에게 알리세요. 기관 관리자가 Tutlio 기술지원팀에 문의합니다.",
  "register.orgPolicyConsent": "플랫폼을 이용하면 다음에 동의하는 것으로 간주됩니다:",
