  "quiz.info.story.company.story": "“Tutlio를 사용하기 전에는 수업 변경, 코멘트, 튜터 수업 시간이 메시지에 흩어져 있었어요. 이제 팀 전체가 같은 시간표를 사용하고 월말에 업데이트를 일일이 확인할 필요가 없어졌습니다.”",
  "quiz.info.story.company.proof1": "팀 일정 관리",
  "quiz.info.story.company.proof2": "맞춤 급여 규칙",
  "quiz.info.story.company.proof3": "수업 현황 관리",
  "quiz.info.story.company.detail": "“가장 큰 차이는 일반적인 절차에 우리를 맞추는 대신, 승인, 보강 수업, 급여 규칙을 우리 팀의 기존 업무 방식에 맞췄다는 점이에요.”",
  "quiz.info.story.school.eyebrow": "Tutlio 고객의 이야기",
  "quiz.info.story.school.title": "VšĮ “Laisvi vaikai”에 생긴 변화",
  "quiz.info.story.school.body": "학생 기록, 계약, 분할 납부, 회계를 하나의 행정 과정으로 연결했습니다.",
  "quiz.info.story.school.disclosure": "고객의 업무 흐름",
  "quiz.info.story.school.brandAlt": "VšĮ “Laisvi vaikai” 로고",
  "quiz.info.story.school.customerName": "VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerType": "학교 행정팀",
  "quiz.info.story.school.story": "“등록과 계약부터 매회 납부까지 가족별 진행 상황을 팀이 한곳에서 확인하고 싶었어요. Tutlio 덕분에 별도의 스프레드시트를 유지하지 않아도 흐름이 이어집니다.”",
  "quiz.info.story.school.proof1": "계약 및 서명",
  "quiz.info.story.school.proof2": "분할 납부 일정",
  "quiz.info.story.school.proof3": "회계 자료 내보내기",
  "quiz.info.story.school.detail": "“가장 확실한 개선은 여러 사람에게 묻거나 다른 파일을 확인하지 않고도 계약, 서명, 결제 상태를 볼 수 있다는 점이에요.”",
  "quiz.businessCard.eyebrow": "성장을 돕는 기본 제공 페이지",
  "quiz.businessCard.title": "링크 하나로 전문적인 첫인상부터 수업 예약까지",
  "quiz.businessCard.body": "Tutlio 디지털 명함은 예비 학생이 수업 내용을 이해하고, 가능한 시간을 확인하고, 수업을 예약할 수 있는 명확한 공간을 제공합니다.",
  "quiz.businessCard.previewAlt": "Tutlio 디지털 명함 및 수업 예약 페이지 미리보기",
