  "quiz.businessCard.benefit3.title": "관심이 생겼을 때 바로 예약하도록",
  "quiz.businessCard.benefit3.body": "새 학생이 긴 메시지 대화를 기다리지 않고 수업과 시간을 선택할 수 있습니다.",
