  "quiz.info.assurance.solo.body": "유용한 시스템은 부담을 빠르게 줄이고 더 많은 기능이 필요할 때만 확장할 수 있어야 합니다.",
  "quiz.info.assurance.solo.point1": "캘린더와 학생 관리부터 시작하고 재무와 자동화는 필요한 속도에 맞춰 추가하세요.",
