  "quiz.offer.testimonials.goTo": "후기 {number} 보기",
  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "화학 및 생물 튜터",
  "quiz.offer.testimonial.solo.copy3": "“공개 페이지와 예약을 하나의 링크로 제공하니 새 학생이 더 빨리 결정해요. 저도 같은 정보를 한 명씩 따로 보낼 필요가 없어졌어요.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "물리 튜터",
  "quiz.offer.testimonial.solo.copy4": "“캘린더에서 수업, 변경 사항, 결제 상태를 바로 확인할 수 있어요. 매일의 행정 업무가 훨씬 짧고 명확해졌습니다.”",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "튜터링 기관 팀",
  "quiz.offer.testimonial.company.copy1": "“수업 변경, 튜터 코멘트, 수업 시간을 별도의 메시지로 받곤 했어요. 이제 행정팀이 하나의 시간표에서 전체 상황을 확인합니다.”",
  "quiz.offer.testimonial.company.name2": "독립 튜터링 센터",
  "quiz.offer.testimonial.company.role2": "소유자 · 튜터 8명",
  "quiz.offer.testimonial.company.copy2": "“예전에는 금요일 저녁마다 급여를 준비하려고 캘린더와 튜터 메시지를 대조했어요. Tutlio에서는 그 확인 작업 대부분이 이미 되어 있습니다.”",
  "quiz.offer.testimonial.company.name3": "언어 튜터링 스튜디오",
  "quiz.offer.testimonial.company.role3": "운영 책임자 · 튜터 14명",
  "quiz.offer.testimonial.company.copy3": "“수업이 변경되면 팀이 같은 업데이트를 즉시 확인해요. 추가 메시지가 줄었고 학부모에게 훨씬 명확하게 답할 수 있게 됐습니다.”",
  "quiz.offer.testimonial.company.name4": "시험 대비 아카데미",
  "quiz.offer.testimonial.company.role4": "재무 담당자 · 튜터 22명",
  "quiz.offer.testimonial.company.copy4": "“수업 유형마다 튜터 급여 규칙이 달라서 월말마다 수동 확인이 많았어요. Tutlio의 업무 흐름 덕분에 훨씬 여유롭게 처리합니다.”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "학교 행정팀",
  "quiz.offer.testimonial.school.copy1": "“가장 확실한 개선은 여러 사람에게 묻거나 다른 파일을 확인하지 않고도 계약, 서명, 결제 상태를 볼 수 있다는 점이에요.”",
  "quiz.offer.testimonial.school.name2": "독립 지역 학교",
  "quiz.offer.testimonial.school.role2": "입학 담당자 · 학생 86명",
