  "quiz.offer.testimonial.school.copy3": "“분할 납부 일정 덕분에 결제 후속 관리가 훨씬 편해졌어요. 목록을 수동으로 다시 만들지 않고 학부모에게 연락하기 전에 납부할 금액을 확인할 수 있습니다.”",
