  "landing.custom.badge": "결정적인 차이",
  "landing.custom.title": "일하는 방식에 맞춰지는 소프트웨어 - 그 반대가 아니라",
  "landing.custom.sub": "학교와 에이전시마다 운영 방식은 조금씩 다릅니다. 표준 흐름이 맞지 않으면 Tutlio를 여러분의 프로세스에 맞춰 조정합니다 - 보통 분기가 아니라 몇 주면 됩니다. 이미 고객을 위해 만든 사례를 소개합니다:",
  "landing.custom.ex1Title": "전자 서명이 가능한 연간 계약",
  "landing.custom.ex1Desc": "한 사립학교는 학부모가 연간 계약을 전자적으로 서명하고 분할 납부하며 모든 입금이 회계용 내보내기에 나타나기를 원했습니다. 이제 이 모든 과정이 Tutlio 안에서 이루어집니다.",
  "landing.custom.ex2Title": "튜터 보수와 수수료 규칙",
  "landing.custom.ex2Desc": "한 에이전시는 과목과 수업 유형에 따라 튜터에게 보수를 지급하고 회사 수수료를 더합니다. 그 규칙을 그대로 구현해 월별 튜터 정산서와 청구서가 자동으로 만들어집니다.",
  "landing.custom.ex3Title": "학부모가 한 번에 수락하는 제안",
  "landing.custom.ex3Desc": "한 학교는 추가 수업을 이메일로 제안하고 학부모가 클릭 한 번으로 수락하기를 원했습니다 - 계정도, 인쇄도 없이. 이제 수락과 청구, 첫 수업 초대가 알아서 진행됩니다.",
  "landing.custom.ex4Title": "여러분의 브랜드, 여러분의 웹사이트에",
  "landing.custom.ex4Desc": "한 기관은 자체 로고와 색상, 그리고 웹사이트에 삽입된 로그인을 원했습니다. 학생과 학부모가 사이트를 떠났다고 느끼지 않도록 말이죠. 이제 Tutlio가 그들의 브랜드로 운영됩니다.",
  "landing.custom.note": "이 중 어느 것도 별도 버전이 아닙니다. 모든 맞춤 기능은 팀이 이미 쓰고 있는 같은 제품의 일부가 되며 이후 업데이트도 모두 포함됩니다.",
  "landing.custom.cta": "어떻게 일하시는지 알려 주세요",
